diff --git a/src/ops/linear/q4/q4_small_t_mma.cu b/src/ops/linear/q4/q4_small_t_mma.cu
index fd371b37..5baeaa47 100644
--- a/src/ops/linear/q4/q4_small_t_mma.cu
+++ b/src/ops/linear/q4/q4_small_t_mma.cu
@@ -18,7 +18,7 @@ using FullGeometry            = Q4DraftHeadGeometry<5120>;
 using OptimizedGeometry       = Q4DraftHeadGeometry<2048>;

 #if defined(GINFER_COMPILED_CC) && \
-    (GINFER_COMPILED_CC == 89 || GINFER_COMPILED_CC >= 120)
+    (GINFER_COMPILED_CC == 86 || GINFER_COMPILED_CC == 89 || GINFER_COMPILED_CC >= 120)
 template <int InputRows>
 struct Q4MuseSmallTGeometry {
     static constexpr int kInputRows    = InputRows;
@@ -74,7 +74,7 @@ bool matches(const Tensor& x, const Weight& weight) {
 }

 #if defined(GINFER_COMPILED_CC) && \
-    (GINFER_COMPILED_CC == 89 || GINFER_COMPILED_CC >= 120)
+    (GINFER_COMPILED_CC == 86 || GINFER_COMPILED_CC == 89 || GINFER_COMPILED_CC >= 120)
 template <int InputRows, int TileCols>
 void launch_muse_tile(const Tensor& x, const Weight& weight, Tensor& out, cudaStream_t stream) {
     using Geometry = Q4MuseSmallTGeometry<InputRows>;
@@ -140,7 +140,7 @@ void launch_q4_draft_head_small_t(const Tensor& x, const Weight& weight, Tensor&
 void launch_q4_muse_small_t(const Tensor& x, const Weight& weight, Tensor& out,
                             cudaStream_t stream) {
 #if defined(GINFER_COMPILED_CC) && \
-    (GINFER_COMPILED_CC == 89 || GINFER_COMPILED_CC >= 120)
+    (GINFER_COMPILED_CC == 86 || GINFER_COMPILED_CC == 89 || GINFER_COMPILED_CC >= 120)
     constexpr int kLastMuseSmallT = GINFER_COMPILED_CC == 89 ? 24 : 16;
     if (x.ne[1] < 2 || x.ne[1] > kLastMuseSmallT || weight.padded_shape[1] != weight.k ||
         !muse_problem(weight.n, weight.k)) {
@@ -168,7 +168,7 @@ void launch_q4_muse_small_t(const Tensor& x, const Weight& weight, Tensor& out,
     (void)weight;
     (void)out;
     (void)stream;
-    throw std::invalid_argument("Q4 Linear Muse small-T requires sm_89 or sm_120a");
+    throw std::invalid_argument("Q4 Linear Muse small-T requires sm_86, sm_89, or sm_120a");
 #endif
 }

diff --git a/src/ops/linear/q4/q4_small_t_mma.cu b/src/ops/linear/q4/q4_small_t_mma.cu
index 5baeaa47..5520eec7 100644
--- a/src/ops/linear/q4/q4_small_t_mma.cu
+++ b/src/ops/linear/q4/q4_small_t_mma.cu
@@ -36,8 +36,13 @@ struct Q4MuseSmallTRows {
 };

 // Thirty-two rows amortize the activation tile while retaining a four-block launch bound with the
-// 8/16-column tiles on Ada and Blackwell and the measured 24-column Ada extension.
+// 8/16-column tiles on Ada and Blackwell and the measured 24-column Ada extension. Ampere uses
+// four K warps so that its scheduler can keep more CTAs resident during the long dependency chain.
+#if GINFER_COMPILED_CC == 86
+using Q4MuseSmallTSchedule = Q4SmallTMmaSchedule<32, 4, 4>;
+#else
 using Q4MuseSmallTSchedule = Q4SmallTMmaSchedule<32, 4>;
+#endif
 using Q4MuseSmallTRows32   = Q4MuseSmallTRows<Q4MuseSmallTSchedule::kRowsPerCta>;
 #endif

diff --git a/src/ops/linear/q4/q4_small_t_mma.cu b/src/ops/linear/q4/q4_small_t_mma.cu
index 5520eec7..5baeaa47 100644
