+++ b/src/ops/linear/q4/q4_small_t_mma.cu
@@ -36,13 +36,8 @@ struct Q4MuseSmallTRows {
 };

 // Thirty-two rows amortize the activation tile while retaining a four-block launch bound with the
-// 8/16-column tiles on Ada and Blackwell and the measured 24-column Ada extension. Ampere uses
-// four K warps so that its scheduler can keep more CTAs resident during the long dependency chain.
-#if GINFER_COMPILED_CC == 86
-using Q4MuseSmallTSchedule = Q4SmallTMmaSchedule<32, 4, 4>;
-#else
+// 8/16-column tiles on Ada and Blackwell and the measured 24-column Ada extension.
 using Q4MuseSmallTSchedule = Q4SmallTMmaSchedule<32, 4>;
-#endif
 using Q4MuseSmallTRows32   = Q4MuseSmallTRows<Q4MuseSmallTSchedule::kRowsPerCta>;
 #endif

diff --git a/src/ops/linear/q4/q4_small_t_mma.cu b/src/ops/linear/q4/q4_small_t_mma.cu
index 5baeaa47..2a977929 100644
--- a/src/ops/linear/q4/q4_small_t_mma.cu
+++ b/src/ops/linear/q4/q4_small_t_mma.cu
@@ -36,9 +36,14 @@ struct Q4MuseSmallTRows {
 };

 // Thirty-two rows amortize the activation tile while retaining a four-block launch bound with the
-// 8/16-column tiles on Ada and Blackwell and the measured 24-column Ada extension.
+// 8/16-column tiles on Ada and Blackwell and the measured 24-column Ada extension. Ampere uses
+// sixteen rows to expose another launch wave while retaining eight independent K warps.
+#if GINFER_COMPILED_CC == 86
+using Q4MuseSmallTSchedule = Q4SmallTMmaSchedule<16, 6>;
+#else
 using Q4MuseSmallTSchedule = Q4SmallTMmaSchedule<32, 4>;
-using Q4MuseSmallTRows32   = Q4MuseSmallTRows<Q4MuseSmallTSchedule::kRowsPerCta>;
+#endif
+using Q4MuseSmallTRowPolicy = Q4MuseSmallTRows<Q4MuseSmallTSchedule::kRowsPerCta>;
 #endif

 template <class Geometry, int TileTokens, int ActiveTokens>
@@ -85,13 +90,13 @@ void launch_muse_tile(const Tensor& x, const Weight& weight, Tensor& out, cudaSt
     }

     const int blocks = rows / Q4MuseSmallTSchedule::kRowsPerCta;
-    q4_small_t_mma_kernel<Geometry, TileCols, 0, Q4SmallTMmaStoreEpilogue, Q4MuseSmallTRows32,
+    q4_small_t_mma_kernel<Geometry, TileCols, 0, Q4SmallTMmaStoreEpilogue, Q4MuseSmallTRowPolicy,
                           Q4MuseSmallTSchedule>
         <<<blocks, Q4MuseSmallTSchedule::kThreads, 0, stream>>>(
             static_cast<const __nv_bfloat16*>(x.data),
             static_cast<const std::uint8_t*>(weight.qdata),
             static_cast<const std::uint8_t*>(weight.scales), static_cast<__nv_bfloat16*>(out.data),
-            Q4SmallTMmaStoreEpilogue{}, Q4MuseSmallTRows32{}, cols, rows);
+            Q4SmallTMmaStoreEpilogue{}, Q4MuseSmallTRowPolicy{}, cols, rows);
     CUDA_CHECK(cudaGetLastError());
 }

